/* REAUDIT SQL045 SQL054 EXECUTABLE SHAPE BEGIN */
-- Required before the first canonical filtered-index definition, independently
-- of the caller's session defaults (the later SQL035 bundle is not early enough).
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET ARITHABORT ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET NUMERIC_ROUNDABORT OFF;
IF OBJECT_ID(N'tempdb..#RA045Identity') IS NOT NULL OR OBJECT_ID(N'tempdb..#RA045State') IS NOT NULL
 OR OBJECT_ID(N'tempdb..#RA045Amount') IS NOT NULL OR OBJECT_ID(N'tempdb..#RA045Json') IS NOT NULL
 OR OBJECT_ID(N'tempdb..#RA045Utc') IS NOT NULL OR OBJECT_ID(N'tempdb..#RA045Actor') IS NOT NULL
 OR OBJECT_ID(N'tempdb..#RA054Identity') IS NOT NULL OR OBJECT_ID(N'tempdb..#RA054Context') IS NOT NULL
 OR OBJECT_ID(N'tempdb..#RA054Content') IS NOT NULL OR OBJECT_ID(N'tempdb..#RA045PendingFilter') IS NOT NULL
 THROW 64554,N'BMS feature metadata probe refused: canonical local temp name is already in use.',1;
-- Canonical CHECK metadata is generated by the same SQL engine from the
-- accepted migration expressions. No business row is read or changed here.
CREATE TABLE #RA045Identity(Id uniqueidentifier,ProposalConcurrencyStamp uniqueidentifier,ConcurrencyStamp uniqueidentifier,SubmissionNumber int,
 CHECK(Id<>'00000000-0000-0000-0000-000000000000' AND ProposalConcurrencyStamp<>'00000000-0000-0000-0000-000000000000'
      AND ConcurrencyStamp<>'00000000-0000-0000-0000-000000000000' AND SubmissionNumber>0));
CREATE TABLE #RA045State(State nvarchar(16),CurrentStageNumber int,
 CHECK((State=N'Pending' AND CurrentStageNumber BETWEEN 1 AND 4)
      OR (State IN(N'Returned',N'Rejected',N'Approved') AND CurrentStageNumber IS NULL)));
CREATE TABLE #RA045Amount(PositiveExcessKzt decimal(18,2),CHECK(PositiveExcessKzt>=0));
CREATE TABLE #RA045Json(CellsJson nvarchar(max),StagesJson nvarchar(max),DecisionsJson nvarchar(max),
 CHECK(ISJSON(CellsJson)=1 AND ISJSON(StagesJson)=1 AND ISJSON(DecisionsJson)=1));
CREATE TABLE #RA045Utc(SubmittedAtUtc datetimeoffset(7),CHECK(DATEPART(TZOFFSET,SubmittedAtUtc)=0));
CREATE TABLE #RA045Actor(SubmittedByExternalId nvarchar(256) COLLATE Latin1_General_100_BIN2,
 CHECK(DATALENGTH(SubmittedByExternalId)>0 AND DATALENGTH(SubmittedByExternalId)=DATALENGTH(LTRIM(RTRIM(SubmittedByExternalId)))));
CREATE TABLE #RA054Identity(Id uniqueidentifier,ActorExternalId nvarchar(256) COLLATE Latin1_General_100_BIN2,
 CHECK(Id<>'00000000-0000-0000-0000-000000000000' AND LEN(ActorExternalId)>0));
CREATE TABLE #RA054Context(SessionId uniqueidentifier,ExpenseRequestId uniqueidentifier,
 CHECK(SessionId IS NOT NULL OR ExpenseRequestId IS NOT NULL));
CREATE TABLE #RA054Content(Id uniqueidentifier,FileSizeBytes bigint,FileName nvarchar(255) COLLATE Latin1_General_100_BIN2,
 StorageKey nvarchar(101) COLLATE Latin1_General_100_BIN2,ContentSha256 binary(32),
 UploadedByExternalId nvarchar(256) COLLATE Latin1_General_100_BIN2,StorageRoot nvarchar(512) COLLATE Latin1_General_100_BIN2,
 Kind nvarchar(30) COLLATE Latin1_General_100_BIN2,
 CHECK(FileSizeBytes BETWEEN 1 AND 26214400 AND LEN(FileName)>0
    AND StorageKey=LOWER(REPLACE(CONVERT(nvarchar(36),Id),N'-',N'')+N'.'+CONVERT(nvarchar(64),ContentSha256,2)+N'.bin') AND LEN(UploadedByExternalId)>0 AND LEN(StorageRoot)>3
    AND Kind IN(N'SUPPORTING',N'NEW_CONTRACT',N'ADDITIONAL')));
CREATE TABLE #RA045PendingFilter(BudgetInstanceId uniqueidentifier,State nvarchar(16));
CREATE UNIQUE INDEX RA045PendingFilter ON #RA045PendingFilter(BudgetInstanceId) WHERE State=N'Pending';

