/* SQL057 BUDGET ADJUSTMENTS SHAPE BEGIN */
-- Extension454 retains the old contract for legacy fixtures. Production also
-- requires ActiveComposition454HealthCheck, which pins the permit and procedure.
IF OBJECT_ID(N'bms_version454.Contract',N'U') IS NOT NULL
BEGIN
 UPDATE @CV048Modules SET DefinitionHash=0x9E2287576DDFF1A7F71834E152AF45FA6A95EA70168A521A26ABD4C6A80C2D38 WHERE Name=N'TR_CompanyBudgetVersions_Immutable';
 UPDATE @CV048Modules SET DefinitionHash=0x17536C7F297C57090ADC55DAEC3499505536E4453FE781288E9E5669C6A60951 WHERE Name=N'TR_CompanyBudgetMembers_Immutable';
END;
DECLARE @Adjustments57Ready bit=0;
IF EXISTS(SELECT 1 FROM bms_web.schema_version WHERE version_no=57
 AND script_name COLLATE Latin1_General_100_BIN2=N'057_budget_instance_adjustments.sql'
 AND DATALENGTH(script_name)=DATALENGTH(N'057_budget_instance_adjustments.sql'))
 AND (SELECT COUNT(*) FROM sys.columns WHERE object_id=OBJECT_ID(N'bms_web.BudgetAdjustments',N'U'))=20
 AND EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'bms_web.BudgetAdjustments')
  AND name=N'TransfersJson' AND system_type_id=231 AND max_length=-1 AND is_nullable=0)
 AND EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'bms_web.BudgetAdjustments')
  AND name=N'Stamp' AND system_type_id=36 AND is_nullable=0)
 AND EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'bms_web.BudgetAdjustments')
  AND name=N'ApprovalOrder' AND system_type_id=56 AND is_nullable=1)
 AND (SELECT COUNT(*) FROM sys.foreign_keys WHERE parent_object_id=OBJECT_ID(N'bms_web.BudgetAdjustments') AND is_disabled=0 AND is_not_trusted=0)=4
 AND (SELECT COUNT(*) FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'bms_web.BudgetAdjustments') AND is_disabled=0 AND is_not_trusted=0)=5
 AND EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'bms_web.BudgetAdjustments') AND name=N'UX_BudgetAdjustments_Base_Sequence' AND is_unique=1 AND is_disabled=0)
 AND EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'bms_web.BudgetAdjustments') AND name=N'UX_BudgetAdjustments_Base_Approval' AND is_unique=1 AND is_disabled=0 AND has_filter=1)
 AND HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'bms_web.v_BudgetInstanceEffectiveLines')))=0xBB3BF2865A16D6C1E9B1344BC4159CC6EEC98B1DB302A1E517C5E17C841016D5
 AND HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'bms_web.TR_BudgetAdjustments_Immutable')))=0x42C2FA5E1D621F72575616434C448297C9343CC53D67C63D5A6FB289EA5EF031
 AND EXISTS(SELECT 1 FROM sys.triggers WHERE object_id=OBJECT_ID(N'bms_web.TR_BudgetAdjustments_Immutable')
  AND parent_id=OBJECT_ID(N'bms_web.BudgetAdjustments') AND is_disabled=0 AND is_instead_of_trigger=0
  AND (SELECT COUNT(*) FROM sys.trigger_events WHERE object_id=OBJECT_ID(N'bms_web.TR_BudgetAdjustments_Immutable'))=3)
 SET @Adjustments57Ready=1;
IF EXISTS(SELECT 1 FROM bms_web.schema_version WHERE version_no=57)
 UPDATE @CV048Modules SET DefinitionHash=0x30AFEC05266056B6B975FC0298DC2039EE8146E16D5332C976334A734F8DC068
 WHERE Name=N'v_CompanyBudgetExecutionPositions';
/* SQL057 BUDGET ADJUSTMENTS SHAPE END */
/* SQL060 VERSION DELETION GUARD BEGIN */
IF EXISTS(SELECT 1 FROM bms_web.schema_version WHERE version_no=60 AND script_name=N'060_company_budget_version_deletions.sql')
 INSERT @CV048Modules VALUES(N'TR_CompanyBudgetActiveVersion_NotDeleted',N'CompanyBudgetActiveVersion','TR',2,
  0x0B859EF31A5D69607FC7187F398DCC2805542CA647C18643398F414B3E3085A5);
/* SQL060 VERSION DELETION GUARD END */
IF EXISTS(SELECT 1 FROM @CV048Modules e LEFT JOIN sys.objects o
 ON o.object_id=OBJECT_ID(N'bms_web.'+e.Name) AND o.type COLLATE Latin1_General_100_BIN2=e.TypeName COLLATE Latin1_General_100_BIN2
 -- Exact UTF-16 DDL bytes preserve BIN2 string literals; do not uppercase
 -- or strip whitespace inside literals while hashing executable finance rules.
 WHERE o.object_id IS NULL OR HASHBYTES('SHA2_256',OBJECT_DEFINITION(o.object_id))<>e.DefinitionHash
 OR OBJECT_DEFINITION(o.object_id) IS NULL
 OR (e.TypeName='TR' AND NOT EXISTS(SELECT 1 FROM sys.triggers t WHERE t.object_id=o.object_id
 AND t.parent_id=OBJECT_ID(N'bms_web.'+e.ParentName) AND t.parent_class=1 AND t.is_disabled=0
 AND t.is_instead_of_trigger=0 AND t.is_not_for_replication=0
 AND (SELECT COUNT(*) FROM sys.trigger_events WHERE object_id=o.object_id)=e.Events)))
 OR EXISTS(SELECT 1 FROM @CV048Tables t JOIN sys.triggers tr ON tr.parent_id=t.ObjectId
 WHERE tr.is_ms_shipped=0 AND NOT EXISTS(SELECT 1 FROM @CV048Modules e
 WHERE e.Name COLLATE Latin1_General_100_BIN2=tr.name COLLATE Latin1_General_100_BIN2
 AND e.ParentName COLLATE Latin1_General_100_BIN2=t.Name COLLATE Latin1_General_100_BIN2))
 SET @CV048Ready=0;
DECLARE @CV048DataReady bit=0;
IF @CV048Ready=1
 EXEC sys.sp_executesql N'SELECT @ok=CASE WHEN
 (SELECT COUNT(*) FROM bms_web.CompanyBudgetActiveVersion)=1
 AND NOT EXISTS(SELECT 1 FROM bms_web.BudgetInstances b WHERE NOT EXISTS
   (SELECT 1 FROM bms_web.CompanyBudgetInstanceCreations c WHERE c.BudgetInstanceId=b.Id))
 AND NOT EXISTS(SELECT 1 FROM bms_web.CompanyBudgetActiveVersion a
 LEFT JOIN bms_web.CompanyBudgetVersions v ON v.Id=a.VersionId
 WHERE a.Id<>1 OR v.Id IS NULL OR v.PublishedAtUtc IS NULL OR v.PublishedInstanceCount IS NULL
 OR v.PublishedInstanceCount<>(SELECT COUNT(*) FROM bms_web.CompanyBudgetVersionInstances m WHERE m.VersionId=v.Id))
 AND NOT EXISTS(SELECT 1 FROM bms_web.CompanyBudgetVersions v WHERE v.PublishedAtUtc IS NOT NULL
 AND (v.PublishedInstanceCount IS NULL OR v.PublishedInstanceCount<>(SELECT COUNT(*) FROM bms_web.CompanyBudgetVersionInstances m WHERE m.VersionId=v.Id)
 OR EXISTS(SELECT 1 FROM bms_web.CompanyBudgetVersionInstances m WHERE m.VersionId=v.Id
 AND NOT EXISTS(SELECT 1 FROM bms_web.BudgetInstances b WHERE b.Id=m.BudgetInstanceId
 AND b.Status COLLATE Latin1_General_100_BIN2=N''Approved'' AND b.ApprovalOrdinal IS NOT NULL AND b.ApprovedAtUtc IS NOT NULL))))
 AND EXISTS(SELECT 1 FROM bms_web.CompanyBudgetActiveVersion a JOIN bms_web.CompanyBudgetActivations h
 ON h.VersionId=a.VersionId AND h.ActiveConcurrencyStamp=a.ConcurrencyStamp)
 THEN 1 ELSE 0 END;',N'@ok bit OUTPUT',@ok=@CV048DataReady OUTPUT;
IF @CV048DataReady<>1 SET @CV048Ready=0;
/* SQL057 CURRENT RUNTIME REQUIREMENT BEGIN */
IF @Adjustments57Ready<>1 SET @CV048Ready=0;
/* SQL057 CURRENT RUNTIME REQUIREMENT END */
/* SQL048 COMPANY VERSION SHAPE END */
IF OBJECT_ID(N'tempdb..#BD034Prefix') IS NOT NULL
   OR OBJECT_ID(N'tempdb..#BD034Stamp') IS NOT NULL
   OR OBJECT_ID(N'tempdb..#BD034Counter') IS NOT NULL
   OR OBJECT_ID(N'tempdb..#BD034Membership') IS NOT NULL
    THROW 63409, N'BMS budget directory refused: canonical local temp name is already in use.', 1;
CREATE TABLE #BD034Prefix
(
    CanonicalPrefix nvarchar(6) COLLATE Latin1_General_100_BIN2 NOT NULL,
    CHECK (DATALENGTH(CanonicalPrefix) BETWEEN 4 AND 12)
);
CREATE TABLE #BD034Stamp
(
    ConcurrencyStamp uniqueidentifier NOT NULL,
    CHECK (ConcurrencyStamp <> CONVERT(uniqueidentifier, '00000000-0000-0000-0000-000000000000'))
);
CREATE TABLE #BD034Counter
(
    LastIssuedOrdinal bigint NOT NULL,
    CHECK (LastIssuedOrdinal >= 0)
);
CREATE TABLE #BD034Membership
(
    MembershipKind nvarchar(16) COLLATE Latin1_General_100_BIN2 NOT NULL,
