                (N'ConcurrencyStamp', N'uniqueidentifier', 16, 0, 0, 0, NULL),
                (N'ApprovalOrdinal', N'bigint', 8, 1, 19, 0, NULL),
                (N'ApprovedAtUtc', N'datetimeoffset', 9, 1, 30, 3, NULL),
