            SELECT COUNT(*)
            FROM sys.check_constraints
            WHERE is_disabled = 0 AND is_not_trusted = 0
              AND is_not_for_replication = 0 AND is_system_named = 0
              AND
              (
                  (parent_object_id = OBJECT_ID(N'bms_web.ExpenseRequests')
                   AND name = N'CK_bms_web_ExpenseRequests_actor'
                   AND parent_column_id = COLUMNPROPERTY(
                       OBJECT_ID(N'bms_web.ExpenseRequests'),
                       N'InitiatorExternalId',
                       N'ColumnId'))
                  OR (parent_object_id = OBJECT_ID(N'bms_web.BusinessAudit')
                      AND name = N'CK_bms_web_BusinessAudit_Actor'
                      AND parent_column_id = COLUMNPROPERTY(
                          OBJECT_ID(N'bms_web.BusinessAudit'),
                          N'ActorExternalId',
                          N'ColumnId'))
                  OR (parent_object_id = OBJECT_ID(N'bms_web.ActorOrganizationGrants')
                      AND name = N'CK_bms_web_ActorOrganizationGrants_Actor'
                      AND parent_column_id = COLUMNPROPERTY(
                          OBJECT_ID(N'bms_web.ActorOrganizationGrants'),
                          N'ActorExternalId',
                          N'ColumnId'))
                  OR (parent_object_id = OBJECT_ID(N'bms_web.ActorCostCenterAccess')
                      AND name = N'CK_bms_web_ActorCostCenterAccess_Actor'
                      AND parent_column_id = COLUMNPROPERTY(
                          OBJECT_ID(N'bms_web.ActorCostCenterAccess'),
                          N'ActorExternalId',
                          N'ColumnId'))
                  OR (parent_object_id = OBJECT_ID(N'bms_web.IdempotencyRecords')
                      AND name = N'CK_bms_web_IdempotencyRecords_hash'
                      AND parent_column_id = COLUMNPROPERTY(
                          OBJECT_ID(N'bms_web.IdempotencyRecords'),
                          N'RequestHash',
                          N'ColumnId'))
                  OR (parent_object_id = OBJECT_ID(N'bms_web.IdempotencyRecords')
                      AND name IN
                      (
                          N'CK_bms_web_IdempotencyRecords_ScopeKeyCanonical',
                          N'CK_bms_web_IdempotencyRecords_KeyBytes'
                      )
                      AND parent_column_id = 0)
              )
        ) = 7
        AND NOT EXISTS
        (
            SELECT 1
            FROM
            (
                VALUES
                    (N'bms_web.ExpenseRequests', N'CK_bms_web_ExpenseRequests_actor',
                     0xF50FA48178CB6C519792DEF105FB9EE607424D1AC68CCE915BBF0A2307388D5D),
                    (N'bms_web.BusinessAudit', N'CK_bms_web_BusinessAudit_Actor',
                     0xA21537EAA13CBC63A1BC163B1CA4A6FB2B1DF070350A43C533FCB10C73FEBED1),
                    (N'bms_web.ActorOrganizationGrants',
                     N'CK_bms_web_ActorOrganizationGrants_Actor',
                     0xA21537EAA13CBC63A1BC163B1CA4A6FB2B1DF070350A43C533FCB10C73FEBED1),
                    (N'bms_web.ActorCostCenterAccess',
                     N'CK_bms_web_ActorCostCenterAccess_Actor',
                     0xA21537EAA13CBC63A1BC163B1CA4A6FB2B1DF070350A43C533FCB10C73FEBED1),
                    (N'bms_web.IdempotencyRecords', N'CK_bms_web_IdempotencyRecords_hash',
                     0x838240DEE5076D11CB4BF62F349071B46B8A871D3C2405D36E62FF12178DE27A),
                    (N'bms_web.IdempotencyRecords',
                     N'CK_bms_web_IdempotencyRecords_ScopeKeyCanonical',
                     0xCEC57B4E8494E16B21D9BCB06B01310B59AFE42DBACEF55B83653BC5B8D5BBE1),
                    (N'bms_web.IdempotencyRecords',
                     N'CK_bms_web_IdempotencyRecords_KeyBytes',
                     0xADB569BEAF4364CE299625FC28CFE88394DA2AB8FFD540FA4F3BA2B614F5F6AE)
