                        N'[ActorExternalId]', N'ActorExternalId'),
                        N'[RequestHash]', N'RequestHash'),
                        N'[Scope]', N'Scope'),
                        N'[Key]', N'Key'),
                        N'(', N''), N')', N''), N' ', N''), CHAR(9), N''), CHAR(10), N''), CHAR(13), N'')
                )
            ) AS normalized(Definition)
            WHERE cc.object_id IS NULL
               OR HASHBYTES(
                   N'SHA2_256',
                   CONVERT(varbinary(max), normalized.Definition)) <> expected.DefinitionHash
        )
        AND NOT EXISTS
        (
            SELECT 1
            FROM
            (
                VALUES
                    (N'bms_web.ExpenseRequests', N'IX_ExpenseRequests_InitiatorExternalId_CreatedAtUtc', 2, 0, 0, 2),
                    (N'bms_web.ActorOrganizationGrants', N'PK_bms_web_ActorOrganizationGrants', 1, 1, 1, 2),
