                  AND pc.name = N'ParentId' AND rc.name = N'Id'
                  AND (SELECT COUNT(*) FROM sys.foreign_key_columns AS x
                       WHERE x.constraint_object_id = fk.object_id) = 1
            )
            AND (SELECT COUNT(*) FROM sys.foreign_keys
                 WHERE parent_object_id = OBJECT_ID(N'bms_web.CashFlowItems')) = 2
            AND (SELECT COUNT(*) FROM sys.check_constraints
                 WHERE parent_object_id = OBJECT_ID(N'bms_web.CashFlowItems')) = CASE
                    WHEN @CashFlowDisplayOrderSchema52Ready=1 THEN 8
                    WHEN @ActualsYearsReady=1 THEN 7
                    WHEN @CatalogDirectionReady=1 THEN 6 ELSE 5 END
            AND NOT EXISTS
            (
                SELECT 1 FROM sys.triggers
                WHERE parent_id = OBJECT_ID(N'bms_web.CashFlowItems')
                  AND name <> N'TR_CashFlowItems_CostCenter'
                  AND is_ms_shipped = 0
            )
        THEN 1 ELSE 0 END AS bit) AS CashFlowItemsReady;

    INSERT INTO @readiness (Ordinal, Ready)
        SELECT 14 AS Ordinal,
        CAST(CASE WHEN
            OBJECT_ID(N'bms_web.ExpenseItems', N'U') IS NOT NULL
            AND (SELECT COUNT(*) FROM sys.columns
                 WHERE object_id = OBJECT_ID(N'bms_web.ExpenseItems')) = 3
            AND NOT EXISTS
            (
                SELECT 1
                FROM
                (
                    VALUES
                        (N'Id', N'uniqueidentifier', 16, 0),
                        (N'Code', N'nvarchar', 18, 0),
                        (N'Name', N'nvarchar', CASE WHEN EXISTS(SELECT 1 FROM bms_web.schema_version WHERE version_no=61
                          AND script_name COLLATE Latin1_General_100_BIN2=N'061_expense_item_name_250.sql'
                          AND DATALENGTH(script_name)=DATALENGTH(N'061_expense_item_name_250.sql')) THEN 500 ELSE 50 END, 0)
                ) AS expected(ColumnName, TypeName, MaxLength, IsNullable)
                LEFT JOIN sys.columns AS c
                  ON c.object_id = OBJECT_ID(N'bms_web.ExpenseItems')
                 AND c.name = expected.ColumnName
                WHERE c.object_id IS NULL
                   OR TYPE_NAME(c.user_type_id) <> expected.TypeName
                   OR c.max_length <> expected.MaxLength
                   OR c.is_nullable <> expected.IsNullable
                   OR c.is_computed <> 0 OR c.default_object_id <> 0
                   OR c.rule_object_id <> 0 OR c.generated_always_type <> 0
                   OR c.is_sparse <> 0 OR c.is_column_set <> 0
                   OR c.encryption_type IS NOT NULL OR c.is_hidden <> 0
                   OR c.is_masked <> 0
                   OR (expected.ColumnName = N'Code' AND
                       c.collation_name COLLATE Latin1_General_100_BIN2 <>
                       N'Latin1_General_100_BIN2')
                   OR (expected.ColumnName = N'Name' AND
                       c.collation_name COLLATE Latin1_General_100_BIN2 <>
                       CAST(DATABASEPROPERTYEX(DB_NAME(), 'Collation') AS nvarchar(128))
                           COLLATE Latin1_General_100_BIN2)
                   OR (expected.ColumnName = N'Id' AND c.collation_name IS NOT NULL)
            )
            AND NOT EXISTS
            (
                SELECT 1
                FROM
                (
                    VALUES
                        (N'PK_bms_web_ExpenseItems', 1, 1, 1, 0, 1),
                        (N'UQ_bms_web_ExpenseItems_Code', 2, 1, 0, 1, 1)
                ) AS expected(IndexName, IndexType, IsUnique, IsPrimaryKey, IsUniqueConstraint, KeyCount)
                LEFT JOIN sys.indexes AS i
                  ON i.object_id = OBJECT_ID(N'bms_web.ExpenseItems')
                 AND i.name = expected.IndexName
                WHERE i.object_id IS NULL OR i.type <> expected.IndexType
                   OR i.is_unique <> expected.IsUnique
                   OR i.is_primary_key <> expected.IsPrimaryKey
                   OR i.is_unique_constraint <> expected.IsUniqueConstraint
                   OR i.is_disabled <> 0 OR i.is_hypothetical <> 0
                   OR i.has_filter <> 0 OR i.filter_definition IS NOT NULL
                   OR i.ignore_dup_key <> 0
                   OR (SELECT COUNT(*) FROM sys.index_columns AS ic
                       WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id) <>
                      expected.KeyCount
            )
            AND (SELECT COUNT(*) FROM sys.key_constraints
                 WHERE parent_object_id = OBJECT_ID(N'bms_web.ExpenseItems')) = 2
            AND (SELECT COUNT(*) FROM sys.indexes
                 WHERE object_id = OBJECT_ID(N'bms_web.ExpenseItems')
                   AND index_id > 0 AND is_unique = 1) = 2
            AND NOT EXISTS
            (
                SELECT 1
                FROM
                (
                    VALUES
                        (N'PK_bms_web_ExpenseItems', 1, N'Id'),
                        (N'UQ_bms_web_ExpenseItems_Code', 1, N'Code')
                ) AS expected(IndexName, KeyOrdinal, ColumnName)
                LEFT JOIN sys.indexes AS i
                  ON i.object_id = OBJECT_ID(N'bms_web.ExpenseItems')
                 AND i.name = expected.IndexName
                LEFT JOIN sys.index_columns AS ic
                  ON ic.object_id = i.object_id AND ic.index_id = i.index_id
                 AND ic.key_ordinal = expected.KeyOrdinal
                LEFT JOIN sys.columns AS c
                  ON c.object_id = ic.object_id AND c.column_id = ic.column_id
                WHERE c.name <> expected.ColumnName OR c.name IS NULL
                   OR ic.is_descending_key <> 0 OR ic.is_included_column <> 0
            )
            AND (SELECT COUNT(*) FROM sys.foreign_keys
                 WHERE parent_object_id = OBJECT_ID(N'bms_web.ExpenseItems')
                    OR referenced_object_id = OBJECT_ID(N'bms_web.ExpenseItems')) = 0
            AND (SELECT COUNT(*) FROM sys.check_constraints
                 WHERE parent_object_id = OBJECT_ID(N'bms_web.ExpenseItems')) = 0
            AND NOT EXISTS
            (
                SELECT 1 FROM sys.triggers
                WHERE parent_id = OBJECT_ID(N'bms_web.ExpenseItems')
                  AND is_ms_shipped = 0
            )
        THEN 1 ELSE 0 END AS bit) AS ExpenseItemsReady;

    INSERT INTO @readiness (Ordinal, Ready)
        SELECT 15 AS Ordinal,
        CAST(CASE WHEN
            OBJECT_ID(N'bms_web.ExpenseRequestLines', N'U') IS NOT NULL
            AND NOT EXISTS
            (
                SELECT 1
                FROM
                (
                    VALUES
                        (N'AccrualSnapshotFormsManagerialAccrual', N'bit', 1, 1),
                        (N'AccrualSnapshotExpenseItemId', N'uniqueidentifier', 16, 1)
                ) AS expected(ColumnName, TypeName, MaxLength, IsNullable)
                LEFT JOIN sys.columns AS c
                  ON c.object_id = OBJECT_ID(N'bms_web.ExpenseRequestLines')
                 AND c.name = expected.ColumnName
                WHERE c.object_id IS NULL
                   OR TYPE_NAME(c.user_type_id) <> expected.TypeName
                   OR c.max_length <> expected.MaxLength
                   OR c.is_nullable <> expected.IsNullable
                   OR c.collation_name IS NOT NULL
                   OR c.is_computed <> 0 OR c.is_identity <> 0
                   OR c.is_rowguidcol <> 0 OR c.is_filestream <> 0
                   OR c.default_object_id <> 0
                   OR c.rule_object_id <> 0 OR c.generated_always_type <> 0
                   OR c.is_sparse <> 0 OR c.is_column_set <> 0
                   OR c.encryption_type IS NOT NULL OR c.is_hidden <> 0
                   OR c.is_masked <> 0
            )
            AND EXISTS
            (
                SELECT 1
                FROM sys.check_constraints AS cc
                CROSS APPLY
                (
                    SELECT REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(
                        cc.definition,
                        N' ', N''), NCHAR(9), N''), NCHAR(10), N''), NCHAR(13), N''),
                        N'[', N''), N']', N''), N'(', N'') AS WithoutOpenParentheses
                ) AS first_pass
                CROSS APPLY
                (
                    SELECT REPLACE(
                        first_pass.WithoutOpenParentheses,
                        N')',
                        N'') AS Definition
                ) AS normalized
                WHERE cc.parent_object_id = OBJECT_ID(N'bms_web.ExpenseRequestLines')
                  AND cc.name = N'CK_bms_web_ExpenseRequestLines_AccrualSnapshot'
                  AND cc.is_disabled = 0
                  AND cc.is_not_trusted = 0
                  AND cc.is_not_for_replication = 0
                  AND cc.is_system_named = 0
                  AND cc.parent_column_id = 0
                  AND normalized.Definition COLLATE Latin1_General_100_BIN2 =
                      @ExpectedAccrualSnapshotCheck COLLATE Latin1_General_100_BIN2
            )
            AND NOT EXISTS
            (
                SELECT 1
                FROM sys.check_constraints
                WHERE parent_object_id = OBJECT_ID(N'bms_web.ExpenseRequestLines')
                  AND
                  (
                      definition LIKE N'%AccrualSnapshotFormsManagerialAccrual%'
                      OR definition LIKE N'%AccrualSnapshotExpenseItemId%'
                  )
                  AND name NOT IN
                  (
                      N'CK_bms_web_ExpenseRequestLines_AccrualSnapshot',
                      N'CK_bms_web_ExpenseRequestLines_ConfirmedClosing'
                  )
            )
            AND NOT EXISTS
            (
                SELECT 1
                FROM sys.index_columns AS ic
                INNER JOIN sys.columns AS c
                  ON c.object_id = ic.object_id
                 AND c.column_id = ic.column_id
                WHERE ic.object_id = OBJECT_ID(N'bms_web.ExpenseRequestLines')
                  AND c.name IN
                  (
                      N'AccrualSnapshotFormsManagerialAccrual',
                      N'AccrualSnapshotExpenseItemId'
                  )
            )
            AND NOT EXISTS
            (
                SELECT 1
                FROM sys.indexes AS i
                WHERE i.object_id = OBJECT_ID(N'bms_web.ExpenseRequestLines')
                  AND
                  (
                      CHARINDEX(
                          N'AccrualSnapshotFormsManagerialAccrual',
                          i.filter_definition COLLATE Latin1_General_100_CI_AS) > 0
                      OR CHARINDEX(
                          N'AccrualSnapshotExpenseItemId',
                          i.filter_definition COLLATE Latin1_General_100_CI_AS) > 0
                  )
            )
            AND NOT EXISTS
            (
                SELECT 1
                FROM sys.foreign_key_columns AS fkc
                WHERE
                (
                    fkc.parent_object_id = OBJECT_ID(N'bms_web.ExpenseRequestLines')
                    AND fkc.parent_column_id IN
                    (
                        COLUMNPROPERTY(
                            OBJECT_ID(N'bms_web.ExpenseRequestLines'),
                            N'AccrualSnapshotFormsManagerialAccrual',
                            'ColumnId'),
                        COLUMNPROPERTY(
                            OBJECT_ID(N'bms_web.ExpenseRequestLines'),
                            N'AccrualSnapshotExpenseItemId',
                            'ColumnId')
                    )
                )
                OR
                (
                    fkc.referenced_object_id = OBJECT_ID(N'bms_web.ExpenseRequestLines')
                    AND fkc.referenced_column_id IN
                    (
                        COLUMNPROPERTY(
                            OBJECT_ID(N'bms_web.ExpenseRequestLines'),
                            N'AccrualSnapshotFormsManagerialAccrual',
                            'ColumnId'),
                        COLUMNPROPERTY(
                            OBJECT_ID(N'bms_web.ExpenseRequestLines'),
                            N'AccrualSnapshotExpenseItemId',
                            'ColumnId')
                    )
                )
            )
            AND NOT EXISTS
            (
                SELECT 1
                FROM sys.triggers
                WHERE parent_id = OBJECT_ID(N'bms_web.ExpenseRequestLines')
                  AND is_ms_shipped = 0
            )
        THEN 1 ELSE 0 END AS bit) AS ExpenseRequestLineAccrualSnapshotReady;

    INSERT INTO @readiness (Ordinal, Ready)
        SELECT 16 AS Ordinal,
        CAST(CASE WHEN EXISTS
        (
            SELECT 1
            FROM bms_web.schema_version
            WHERE version_no = 12
              AND script_name COLLATE Latin1_General_100_BIN2 =
                  N'012_money_decimal18_scale2.sql'
              AND DATALENGTH(script_name) =
                  DATALENGTH(N'012_money_decimal18_scale2.sql')
        ) THEN 1 ELSE 0 END AS bit) AS Version12Applied;

    INSERT INTO @readiness (Ordinal, Ready)
        SELECT 17 AS Ordinal,
        CAST(CASE WHEN NOT EXISTS
        (
            SELECT 1
            FROM
            (
                VALUES
                    (N'bms_web.ExpenseRequestLines', N'Amount', 0, 0),
                    (N'bms_web.ExpenseRequestLines', N'VatAmount', 1, 0),
                    (N'bms_web.ExpenseRequestLines', N'AmountExcludingVat', 1, 0),
                    (N'bms_web.ExpenseRequestLines', N'AmountKzt', 1, 0),
                    (N'bms_web.ExpenseRequestLines', N'VatAmountKzt', 1, 0),
                    (N'bms_web.ExpenseRequestLines', N'AmountExcludingVatKzt', 1, 0),
                    (N'bms_web.BudgetPositions', N'LimitAmountKzt', 1, 0),
                    (N'bms_web.BudgetPositions', N'ReservedAmountKzt', 0, 1),
                    (N'bms_web.BudgetPositions', N'PaidAmountKzt', 0, 1),
                    (N'bms_web.BudgetRequestProjections', N'ReservedAmountKzt', 0, 0)
            ) AS expected(ObjectName, ColumnName, IsNullable, HasDefault)
            LEFT JOIN sys.columns AS c
              ON c.object_id = OBJECT_ID(expected.ObjectName)
             AND c.name = expected.ColumnName
            WHERE c.object_id IS NULL
               OR TYPE_NAME(c.user_type_id) <> N'decimal'
               OR c.max_length <> 9
               OR c.[precision] <> 18
               OR c.scale <> 2
               OR c.is_nullable <> expected.IsNullable
               OR CASE WHEN c.default_object_id = 0 THEN 0 ELSE 1 END <>
                  expected.HasDefault
               OR c.collation_name IS NOT NULL
               OR c.is_computed <> 0 OR c.is_identity <> 0
               OR c.is_rowguidcol <> 0 OR c.is_filestream <> 0
               OR c.rule_object_id <> 0 OR c.generated_always_type <> 0
               OR c.is_sparse <> 0 OR c.is_column_set <> 0
               OR c.encryption_type IS NOT NULL OR c.is_hidden <> 0
               OR c.is_masked <> 0
        )
        AND NOT EXISTS
        (
            SELECT 1
            FROM
            (
                VALUES
                    (N'bms_web.BudgetPositions', N'ReservedAmountKzt',
                     N'DF_bms_web_BudgetPositions_Reserved'),
                    (N'bms_web.BudgetPositions', N'PaidAmountKzt',
                     N'DF_bms_web_BudgetPositions_Paid')
            ) AS expected(ObjectName, ColumnName, ConstraintName)
            LEFT JOIN sys.default_constraints AS dc
              ON dc.parent_object_id = OBJECT_ID(expected.ObjectName)
             AND dc.parent_column_id =
                 COLUMNPROPERTY(OBJECT_ID(expected.ObjectName), expected.ColumnName, 'ColumnId')
             AND dc.name = expected.ConstraintName
            WHERE dc.object_id IS NULL
               OR REPLACE(REPLACE(REPLACE(dc.definition, N'(', N''), N')', N''), N' ', N'')
                  COLLATE Latin1_General_100_BIN2 <> N'0'
        )
        AND NOT EXISTS
        (
            SELECT 1
            FROM
            (
                VALUES
                    (N'bms_web.ExpenseRequestLines',
                     N'CK_bms_web_ExpenseRequestLines_amount',
                     N'Amount>0'),
                    (N'bms_web.ExpenseRequestLines',
                     N'CK_ExpenseRequestLines_CalculatedAmounts',
                     @ExpectedLineCurrencyConversionCheck),
                    (N'bms_web.BudgetPositions',
                     N'CK_bms_web_BudgetPositions_limit',
                     N'LimitAmountKztISNULLORLimitAmountKzt>=0'),
                    (N'bms_web.BudgetPositions',
                     N'CK_bms_web_BudgetPositions_reserved',
                     N'ReservedAmountKzt>=0'),
                    (N'bms_web.BudgetPositions',
                     N'CK_bms_web_BudgetPositions_paid',
                     N'PaidAmountKzt>=0'),
                    (N'bms_web.BudgetRequestProjections',
                     N'CK_bms_web_BudgetRequestProjections_reserved',
                     N'ReservedAmountKzt>0')
            ) AS expected(ObjectName, ConstraintName, NormalizedDefinition)
            LEFT JOIN sys.check_constraints AS cc
              ON cc.parent_object_id = OBJECT_ID(expected.ObjectName)
             AND cc.name = expected.ConstraintName
            CROSS APPLY
            (
                VALUES
                (
                    REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(
                        cc.definition, N'[', N''), N']', N''), N'(', N''), N')', N''),
                        N' ', N''), CHAR(9), N''), CHAR(10), N''), CHAR(13), N'')
                )
            ) AS normalized(Definition)
            WHERE cc.object_id IS NULL
               OR cc.is_disabled <> 0 OR cc.is_not_trusted <> 0
               OR cc.is_not_for_replication <> 0 OR cc.is_system_named <> 0
               OR
               (
                   (expected.ConstraintName = N'CK_bms_web_ExpenseRequestLines_amount'
                    AND cc.parent_column_id <> COLUMNPROPERTY(
                        OBJECT_ID(expected.ObjectName),
                        N'Amount',
                        N'ColumnId'))
                   OR (expected.ConstraintName =
                           N'CK_ExpenseRequestLines_CalculatedAmounts'
                       AND cc.parent_column_id <> 0)
                   OR (expected.ConstraintName = N'CK_bms_web_BudgetPositions_limit'
                       AND cc.parent_column_id <> COLUMNPROPERTY(
                           OBJECT_ID(expected.ObjectName),
                           N'LimitAmountKzt',
                           N'ColumnId'))
                   OR (expected.ConstraintName = N'CK_bms_web_BudgetPositions_reserved'
                       AND cc.parent_column_id <> COLUMNPROPERTY(
                           OBJECT_ID(expected.ObjectName),
                           N'ReservedAmountKzt',
                           N'ColumnId'))
                   OR (expected.ConstraintName = N'CK_bms_web_BudgetPositions_paid'
                       AND cc.parent_column_id <> COLUMNPROPERTY(
                           OBJECT_ID(expected.ObjectName),
                           N'PaidAmountKzt',
                           N'ColumnId'))
                   OR (expected.ConstraintName =
                           N'CK_bms_web_BudgetRequestProjections_reserved'
                       AND cc.parent_column_id <> COLUMNPROPERTY(
                           OBJECT_ID(expected.ObjectName),
                           N'ReservedAmountKzt',
                           N'ColumnId'))
               )
               OR normalized.Definition COLLATE Latin1_General_100_BIN2 <>
                  expected.NormalizedDefinition COLLATE Latin1_General_100_BIN2
        )
        AND NOT EXISTS
        (
            SELECT 1
            FROM sys.check_constraints AS cc
            WHERE
            (
                (cc.parent_object_id = OBJECT_ID(N'bms_web.ExpenseRequestLines')
                 AND cc.definition COLLATE Latin1_General_100_CI_AS LIKE N'%Amount%')
             OR (cc.parent_object_id = OBJECT_ID(N'bms_web.BudgetPositions')
                 AND
                 (cc.definition COLLATE Latin1_General_100_CI_AS LIKE N'%LimitAmountKzt%'
                  OR cc.definition COLLATE Latin1_General_100_CI_AS LIKE N'%ReservedAmountKzt%'
                  OR cc.definition COLLATE Latin1_General_100_CI_AS LIKE N'%PaidAmountKzt%'))
             OR (cc.parent_object_id = OBJECT_ID(N'bms_web.BudgetRequestProjections')
                 AND cc.definition COLLATE Latin1_General_100_CI_AS LIKE N'%ReservedAmountKzt%')
            )
              AND cc.name NOT IN
              (
                  N'CK_bms_web_ExpenseRequestLines_amount',
                  N'CK_ExpenseRequestLines_CalculatedAmounts',
                  N'CK_bms_web_ExpenseRequestLines_ConfirmedClosing',
                  N'CK_bms_web_BudgetPositions_limit',
                  N'CK_bms_web_BudgetPositions_reserved',
                  N'CK_bms_web_BudgetPositions_paid',
                  N'CK_bms_web_BudgetRequestProjections_reserved'
              )
        )
        THEN 1 ELSE 0 END AS bit) AS MoneyPrecisionReady;

