                AND name=N'UX_bms_web_BudgetInstanceLines_Key' AND is_unique=0 AND type=2
                AND is_disabled=0 AND is_hypothetical=0 AND has_filter=0)
            THEN 1 ELSE 0 END AS bit) AS Version46Applied,
        CAST(CASE WHEN EXISTS(SELECT 1 FROM bms_web.schema_version WHERE version_no=47
            AND script_name COLLATE Latin1_General_100_BIN2=N'047_budget_instance_line_list_covering.sql'
            AND DATALENGTH(script_name)=DATALENGTH(N'047_budget_instance_line_list_covering.sql'))
            THEN 1 ELSE 0 END AS bit) AS Version47Applied,
        CAST(CASE WHEN @CV048Ready=1 AND EXISTS(SELECT 1 FROM bms_web.schema_version WHERE version_no=48
            AND script_name COLLATE Latin1_General_100_BIN2=N'048_company_budget_versions.sql'
            AND DATALENGTH(script_name)=DATALENGTH(N'048_company_budget_versions.sql'))
            THEN 1 ELSE 0 END AS bit) AS Version48Applied,
        CAST(CASE WHEN @CfoMetadataReady=1 AND @ActualsRegistryReady=1
            AND EXISTS(SELECT 1 FROM bms_web.schema_version WHERE version_no=49
                AND script_name COLLATE Latin1_General_100_BIN2=N'049_cost_center_directory_metadata.sql'
                AND DATALENGTH(script_name)=DATALENGTH(N'049_cost_center_directory_metadata.sql'))
            THEN 1 ELSE 0 END AS bit) AS Version49Applied,
        CAST(CASE WHEN @CatalogDirectionReady=1 AND @ActualsRegistryReady=1
            AND EXISTS(SELECT 1 FROM bms_web.schema_version WHERE version_no=50
                AND script_name COLLATE Latin1_General_100_BIN2=N'050_cash_flow_catalog_direction.sql'
                AND DATALENGTH(script_name)=DATALENGTH(N'050_cash_flow_catalog_direction.sql'))
            THEN 1 ELSE 0 END AS bit) AS Version50Applied,
        CAST(CASE WHEN @ActualsRegistryReady=1 AND @ActualsYearsReady=1
            AND (SELECT COUNT(*) FROM bms_web.schema_version WHERE version_no NOT IN(56,57,58,59,60,61)) IN(50,51,52,53,54)
            THEN 1 ELSE 0 END AS bit) AS Version51Applied,
        CAST(@CashFlowDisplayOrderCompatible AS bit) AS CashFlowDisplayOrderCompatible,
        CAST(CASE WHEN @ActualsRegistryReady=1 AND @CashFlowDisplayOrderSchema52Ready=1
            AND (SELECT COUNT(*) FROM bms_web.schema_version WHERE version_no NOT IN(56,57,58,59,60,61)) IN(51,52,53,54)
            THEN 1 ELSE 0 END AS bit) AS Version52Applied,
        CAST(CASE WHEN @ActualsRegistryReady=1 AND @NumberLeaseSchema53Ready=1
            AND (SELECT COUNT(*) FROM bms_web.schema_version WHERE version_no NOT IN(56,57,58,59,60,61)) IN(52,53,54)
            THEN 1 ELSE 0 END AS bit) AS Version53Applied,
        CAST(CASE WHEN @ActualsRegistryReady=1 AND @PrivateAttachmentSchema54Ready=1
            AND (SELECT COUNT(*) FROM bms_web.schema_version WHERE version_no NOT IN(56,57,58,59,60,61)) IN(53,54) THEN 1 ELSE 0 END AS bit) AS Version54Applied
    FROM @readiness AS readiness;
END;
